import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFraunces = makeLoadFont('Fraunces');

// Load Google Font at module level to ensure it's ready before frame 0
const { fontFamily: frauncesFamily } = loadFraunces();



export type GlowingTextProps = Record<string, any>;

const GlowingTextAd: React.FC<GlowingTextProps> = ({
  backgroundColor = "#060d05",
  transparentBackground = false,
  durationInSeconds = 5,
  textLines = ["DON’T", "LET META", "SABOTAGE", "YOUR ADS"],
  textColor = "#ade49c",
  glowColor = "#5ea647", // slightly darker green for the outer glow to give depth
  glowIntensity = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Canvas scale factor for responsive design
  const s = Math.min(width, height) / 1080;

  // Handle transparent background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global slow cinematic zoom in to give continuous motion after entrance
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1.08],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          display: "flex",
          flexDirection: "column",
          transform: `scale(${globalScale})`,
          transition: "none",
        }}
      >
        {textLines.map((line, i) => {
          // Stagger the entrance of each line
          const startFrame = i * 7;
          
          // Spring for scale and vertical drift
          const progress = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, stiffness: 60, mass: 0.8 },
          });

          // Opacity fades in over 15 frames. 
          // extrapolateLeft: "clamp" ensures opacity is exactly 0 on all frames before startFrame.
          const lineOpacity = interpolate(
            frame - startFrame,
            [0, 15],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Lines scale down slightly as they enter
          const scale = interpolate(progress, [0, 1], [1.15, 1]);
          
          // Lines drift upwards to their final resting position
          const yOffset = interpolate(progress, [0, 1], [60 * s, 0]);

          // Compute responsive blur radii for the multi-layered text shadow
          const blur1 = glowIntensity * 0.4 * s;
          const blur2 = glowIntensity * 1.5 * s;
          const blur3 = glowIntensity * 3.5 * s;
          
          // The base text is the lighter textColor, the glow is the glowColor
          const shadow = `
            0 0 ${blur1}px ${textColor}, 
            0 0 ${blur2}px ${glowColor}, 
            0 0 ${blur3}px ${glowColor}
          `;

          return (
            <div
              key={i}
              style={{
                opacity: lineOpacity,
                transform: `scale(${scale}) translateY(${yOffset}px)`,
                fontSize: `${185 * s}px`, // Dynamically sized to fill a 1080 canvas nicely
                fontFamily: frauncesFamily,
                fontWeight: 700,
                color: textColor,
                lineHeight: 0.85, // Tightly packed lines like the reference
                textTransform: "uppercase",
                letterSpacing: `${-6 * s}px`, // Tight tracking
                whiteSpace: "nowrap",
                textShadow: shadow,
                transition: "none",
              }}
            >
              {line}
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default GlowingTextAd;